-- 18.6 keys a cast on its argument's *strength* — transparent at 2, substituting its own
-- type name at ≤ 1 — so an **unaliased** `x::regclass::text` is named after `x` and a
-- literal one after the cast the stack ends at. Modelling `::regclass` as a scalar
-- function leaked the function's name into both, which the harness sees because it keys
-- each compared row by its column name — every other fixture aliases, so none of them
-- could.
-- The two projections take the rule's two arms: a named inner expression keeps its name
-- through both casts, and a nameless one (a literal) takes the type of the **one** cast
-- standing above the `regclass` here. With a second cast above,
-- `'zz'::regclass::text::varchar` is `text` here and `varchar` there (`EDGES.md`
-- row 117). A bare `x::regclass` is deliberately absent — its value is an OID
-- there and a name here (`EDGES.md`), so comparing it would be red for a reason
-- that is not this fixture's.
-- @setup
CREATE TYPE cat_mood AS ENUM ('sad', 'ok', 'happy');
CREATE TABLE cat_parent (
  id INT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  code TEXT NOT NULL,
  region VARCHAR(8) NOT NULL,
  CONSTRAINT cat_parent_code_region_uq UNIQUE (code, region)
);
CREATE TABLE cat_child (
  cid INT GENERATED BY DEFAULT AS IDENTITY,
  pid INT REFERENCES cat_parent(id) ON DELETE CASCADE,
  qty INT NOT NULL,
  label TEXT,
  price NUMERIC(10,2),
  m cat_mood,
  CONSTRAINT cat_child_qty_positive CHECK (qty > 0),
  -- Two columns, named out of position order: `conkey` is 18.6's `pull_var_clause`
  -- walk order (`{3,2}`), not the table's column order. Integer operands only —
  -- a text literal would drag in the deparser's recorded `''` vs `''::text`
  -- divergence, which is not this constraint's subject.
  CONSTRAINT cat_child_qty_pid CHECK (qty > 1 AND pid > 0)
);
CREATE INDEX cat_child_pid_idx ON cat_child (pid);
CREATE INDEX cat_child_lower_label_idx ON cat_child (lower(label));
CREATE INDEX cat_child_partial_idx ON cat_child (qty) WHERE qty > 10;
CREATE SEQUENCE cat_plain_seq START 5;

-- @test
SELECT c.conrelid::regclass::text, 'cat_parent'::regclass::text
FROM pg_constraint c
JOIN pg_class k ON k.oid = c.conrelid
WHERE k.relname::text = 'cat_parent' AND c.contype::text = 'p'
